import { createHmac, timingSafeEqual } from 'node:crypto';
export class JsonHttpClient{constructor(private baseUrl:string,private apiKey:string){}async request(path:string,{method='GET',body,idempotencyKey}:any={}){const response=await fetch(`${this.baseUrl}${path}`,{method,headers:{authorization:`Bearer ${this.apiKey}`,'content-type':'application/json',...(idempotencyKey?{'idempotency-key':idempotencyKey}:{})},body:body===undefined?undefined:JSON.stringify(body)});const text=await response.text();if(!response.ok)throw new Error(`PROVIDER_${response.status}:${text.slice(0,200)}`);return text?JSON.parse(text):{};}}
export class HttpPayoutProvider{private client:JsonHttpClient;constructor(baseUrl:string,apiKey:string){this.client=new JsonHttpClient(baseUrl,apiKey);}createBeneficiary(input:any){return this.client.request('/beneficiaries',{method:'POST',body:input,idempotencyKey:input.idempotencyKey});}sendPayout(input:any){return this.client.request('/payouts',{method:'POST',body:input,idempotencyKey:input.idempotencyKey});}getPayout(reference:string){return this.client.request(`/payouts/${encodeURIComponent(reference)}`);}}
export class HttpVerificationProvider{private client:JsonHttpClient;constructor(baseUrl:string,apiKey:string){this.client=new JsonHttpClient(baseUrl,apiKey);}createBusinessCheck(input:any){return this.client.request('/business-checks',{method:'POST',body:input,idempotencyKey:input.idempotencyKey});}getCheck(reference:string){return this.client.request(`/business-checks/${encodeURIComponent(reference)}`);}}
export class HttpTaxProvider{private client:JsonHttpClient;constructor(baseUrl:string,apiKey:string){this.client=new JsonHttpClient(baseUrl,apiKey);}quote(input:any){return this.client.request('/tax/quote',{method:'POST',body:input,idempotencyKey:input.idempotencyKey||`${input.sellerCountry}:${input.buyerCountry}:${input.money.amountMinor}`});}}
export class HttpConsentProvider{private client:JsonHttpClient;constructor(baseUrl:string,apiKey:string){this.client=new JsonHttpClient(baseUrl,apiKey);}evaluate(input:any){return this.client.request('/consent/evaluate',{method:'POST',body:input});}}
export class S3CompatibleStorageProvider{constructor(private endpoint:string,private publicBaseUrl:string){}async createUpload(input:any){const key=encodeURIComponent(input.key);return {uploadUrl:`${this.endpoint}/${key}?expires=${input.expiresInSeconds}`,headers:{'content-type':input.contentType,'x-content-sha256':input.checksum},assetUrl:`${this.publicBaseUrl}/${key}`};}async delete(key:string){const response=await fetch(`${this.endpoint}/${encodeURIComponent(key)}`,{method:'DELETE'});if(!response.ok)throw new Error(`STORAGE_${response.status}`);}}
export function verifyHmac(rawBody:string,signature:string,secret:string){const expected=createHmac('sha256',secret).update(rawBody).digest();const actual=Buffer.from(signature,'hex');return actual.length===expected.length&&timingSafeEqual(actual,expected);}
